let file = """{"version":3,"file":"assetPreviewUtil-bcEbjMqP.js","names":[],"sources":["../../src/platform/assets/utils/assetTypeUtil.ts","../../src/platform/assets/utils/assetUrlUtil.ts","../../src/platform/assets/utils/assetPreviewUtil.ts"],"sourcesContent":["/**\n * Utilities for working with asset types\n */\n\nimport type { AssetItem } from '../schemas/assetSchema'\n\n/**\n * Extract asset type from an asset's tags array\n * Falls back to a default type if tags are not present\n *\n * @param asset The asset to extract type from\n * @param defaultType Default type to use if tags are empty (default: 'output')\n * @returns The asset type ('input', 'output', 'temp', etc.)\n *\n * @example\n * getAssetType(asset) // Returns 'output' or first tag\n * getAssetType(asset, 'input') // Returns 'input' if no tags\n */\nexport function getAssetType(\n  asset: AssetItem,\n  defaultType: 'input' | 'output' = 'output'\n): string {\n  const urlType = new URLSearchParams(\n    (asset.preview_url ?? '').split('?')[1] ?? ''\n  ).get('type')\n  return urlType || asset.tags[0] || defaultType\n}\n","/**\n * Utilities for constructing asset URLs\n */\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { api } from '@/scripts/api'\nimport { isResultItemType } from '@/utils/typeGuardUtil'\nimport { getOutputAssetMetadata } from '../schemas/assetMetadataSchema'\nimport type { AssetItem } from '../schemas/assetSchema'\nimport { getAssetType } from './assetTypeUtil'\n\n/**\n * Get the download/view URL for an asset\n * Constructs the proper URL with filename encoding, type, and subfolder parameters\n *\n * @param asset The asset to get URL for\n * @param defaultType Default type if asset doesn't have tags (default: 'output')\n * @returns Full URL for viewing/downloading the asset\n *\n * @example\n * const url = getAssetUrl(asset)\n * downloadFile(url, asset.name)\n */\nexport function getAssetUrl(\n  asset: AssetItem,\n  defaultType: 'input' | 'output' = 'output'\n): string {\n  const assetType = getAssetType(asset, defaultType)\n  const subfolder = getAssetSubfolder(asset)\n  const params = new URLSearchParams()\n  params.set('filename', asset.name)\n  params.set('type', assetType)\n  if (subfolder) {\n    params.set('subfolder', subfolder)\n  }\n  return api.apiURL(`/view?${params}`)\n}\n\n/** `/view` URL of the asset's own file, not its preview. */\nexport function getAssetViewUrl(asset: AssetItem): string {\n  const root = asset.tags.find(isResultItemType)\n  if (!asset.loader_path || !root) return getAssetUrl(asset)\n  const slash = asset.loader_path.lastIndexOf('/')\n  const params = new URLSearchParams({\n    filename: asset.loader_path.slice(slash + 1),\n    type: root\n  })\n  if (slash > 0) params.set('subfolder', asset.loader_path.slice(0, slash))\n  return api.apiURL(`/view?${params}`)\n}\n\n/**\n * Get the subfolder an asset lives in, relative to its type root\n *\n * Reads `preview_url` first and falls back to `user_metadata`, mirroring how\n * {@link getAssetType} resolves the type.\n *\n * @param asset The asset to get the subfolder for\n * @returns The subfolder, or an empty string when the asset is at the root\n */\nexport function getAssetSubfolder(asset: AssetItem): string {\n  const previewSubfolder = new URLSearchParams(\n    (asset.preview_url ?? '').split('?')[1] ?? ''\n  ).get('subfolder')\n  if (previewSubfolder) return previewSubfolder\n\n  const { subfolder } = asset.user_metadata ?? {}\n  return typeof subfolder === 'string' ? subfolder : ''\n}\n\n/**\n * Id of the assets-API asset holding this item's own file. A card grouped per\n * job carries the job id as its `id` and keeps its own asset id in metadata.\n */\nexport function getAssetContentId(\n  asset: Pick<AssetItem, 'id' | 'user_metadata'>\n): string {\n  return getOutputAssetMetadata(asset.user_metadata)?.assetId || asset.id\n}\n\n/**\n * URL of the asset's own file, for downloading or loading it whole.\n *\n * With the assets API enabled the file is served by id, so no path inference\n * is needed and a preview that is only a thumbnail is never mistaken for the\n * file. Otherwise the item came from the history API, whose `preview_url`\n * already points at the file, with a `/view` URL as fallback.\n *\n * `disposition: 'inline'` asks the assets-API content endpoint to serve the\n * file for in-page rendering (e.g. a `<video>` source) instead of its\n * default `attachment` disposition, which browsers try to save rather than\n * play. It has no effect on the history-backed fallback, whose `/view`\n * endpoint has no such distinction.\n */\nexport function getAssetFileUrl(\n  asset: AssetItem,\n  options?: { disposition?: 'inline' | 'attachment' }\n): string {\n  if (useFeatureFlags().flags.assetsEnabled) {\n    const query = options?.disposition\n      ? `?disposition=${options.disposition}`\n      : ''\n    return api.apiURL(`/assets/${getAssetContentId(asset)}/content${query}`)\n  }\n  return asset.preview_url || getAssetUrl(asset)\n}\n","import { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport { api } from '@/scripts/api'\nimport { useAssetsStore } from '@/stores/assetsStore'\n\nimport { getAssetContentId } from './assetUrlUtil'\n\ninterface AssetRecord {\n  id: string\n  name: string\n  hash?: string | null\n  preview_url?: string\n  preview_id?: string | null\n  user_metadata?: Record<string, unknown>\n}\n\n/**\n * Whether the backend can serve asset preview/thumbnail data.\n */\nexport function isAssetPreviewSupported(): boolean {\n  return useFeatureFlags().flags.assetsEnabled\n}\n\nasync function fetchAssets(\n  params: Record<string, string>\n): Promise<AssetRecord[]> {\n  const query = new URLSearchParams(params)\n  const res = await api.fetchApi(`/assets?${query}`)\n  if (!res.ok) return []\n  const data = await res.json()\n  return data.assets ?? []\n}\n\nexport function resolvePreviewUrl(asset: AssetRecord): string {\n  if (asset.preview_url) return api.apiURL(asset.preview_url)\n\n  const contentId = asset.preview_id ?? getAssetContentId(asset)\n  return api.apiURL(`/assets/${contentId}/content`)\n}\n\n/**\n * Find an output asset record by content hash, falling back to name.\n * On cloud, output filenames are content-hashed; use hash to match.\n * On local, filenames are not hashed; use name_contains to match.\n */\nexport async function findOutputAsset(\n  name: string\n): Promise<AssetRecord | undefined> {\n  const byHash = await fetchAssets({ hash: name })\n  const hashMatch = byHash.find((a) => a.hash === name)\n  if (hashMatch) return hashMatch\n\n  const byName = await fetchAssets({ name_contains: name })\n  return byName.find((a) => a.name === name)\n}\n\nexport async function findServerPreviewUrl(\n  name: string\n): Promise<string | null> {\n  try {\n    const asset = await findOutputAsset(name)\n    if (!asset?.preview_id) return null\n\n    return resolvePreviewUrl(asset)\n  } catch {\n    return null\n  }\n}\n\nexport async function persistThumbnail(\n  name: string,\n  blob: Blob\n): Promise<void> {\n  try {\n    const asset = await findOutputAsset(name)\n    if (!asset || asset.preview_id) return\n\n    const previewFilename = `${asset.name}_preview.png`\n    const uploaded = await assetService.uploadAssetFromBase64({\n      data: await blobToDataUrl(blob),\n      name: previewFilename,\n      tags: ['output'],\n      user_metadata: { filename: previewFilename }\n    })\n\n    await assetService.updateAsset(asset.id, {\n      preview_id: uploaded.id\n    })\n    await useAssetsStore().outputAssets.invalidate()\n  } catch {\n    // Non-critical — client still shows the rendered thumbnail\n  }\n}\n\nfunction blobToDataUrl(blob: Blob): Promise<string> {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader()\n    reader.onload = () => resolve(reader.result as string)\n    reader.onerror = reject\n    reader.readAsDataURL(blob)\n  })\n}\n"],"mappings":"0PAkBA,SAAgB,aACd,EACA,EAAkC,SAC1B,CAIR,OAHgB,IAAI,iBACjB,EAAM,aAAe,GAAA,CAAI,MAAM,GAAG,CAAC,CAAC,IAAM,EAC7C,CAAC,CAAC,IAAI,MACC,GAAW,EAAM,KAAK,IAAM,CACrC,CCHA,SAAgB,YACd,EACA,EAAkC,SAC1B,CACR,IAAM,EAAY,aAAa,EAAO,CAAW,EAC3C,EAAY,kBAAkB,CAAK,EACnC,EAAS,IAAI,gBAMnB,OALA,EAAO,IAAI,WAAY,EAAM,IAAI,EACjC,EAAO,IAAI,OAAQ,CAAS,EACxB,GACF,EAAO,IAAI,YAAa,CAAS,EAE5B,EAAI,OAAO,SAAS,GAAQ,CACrC,CAGA,SAAgB,gBAAgB,EAA0B,CACxD,IAAM,EAAO,EAAM,KAAK,KAAK,CAAgB,EAC7C,GAAI,CAAC,EAAM,aAAe,CAAC,EAAM,OAAO,YAAY,CAAK,EACzD,IAAM,EAAQ,EAAM,YAAY,YAAY,GAAG,EACzC,EAAS,IAAI,gBAAgB,CACjC,SAAU,EAAM,YAAY,MAAM,EAAQ,CAAC,EAC3C,KAAM,CACR,CAAC,EAED,OADI,EAAQ,GAAG,EAAO,IAAI,YAAa,EAAM,YAAY,MAAM,EAAG,CAAK,CAAC,EACjE,EAAI,OAAO,SAAS,GAAQ,CACrC,CAWA,SAAgB,kBAAkB,EAA0B,CAC1D,IAAM,EAAmB,IAAI,iBAC1B,EAAM,aAAe,GAAA,CAAI,MAAM,GAAG,CAAC,CAAC,IAAM,EAC7C,CAAC,CAAC,IAAI,WAAW,EACjB,GAAI,EAAkB,OAAO,EAE7B,GAAM,CAAE,aAAc,EAAM,eAAiB,CAAC,EAC9C,OAAO,OAAO,GAAc,SAAW,EAAY,EACrD,CAMA,SAAgB,kBACd,EACQ,CACR,OAAO,EAAuB,EAAM,aAAa,CAAC,EAAE,SAAW,EAAM,EACvE,CAgBA,SAAgB,gBACd,EACA,EACQ,CACR,GAAI,EAAgB,CAAC,CAAC,MAAM,cAAe,CACzC,IAAM,EAAQ,GAAS,YACnB,gBAAgB,EAAQ,cACxB,GACJ,OAAO,EAAI,OAAO,WAAW,kBAAkB,CAAK,EAAE,UAAU,GAAO,CACzE,CACA,OAAO,EAAM,aAAe,YAAY,CAAK,CAC/C,CCtFA,SAAgB,yBAAmC,CACjD,OAAO,EAAgB,CAAC,CAAC,MAAM,aACjC,CAEA,eAAe,YACb,EACwB,CACxB,IAAM,EAAQ,IAAI,gBAAgB,CAAM,EAClC,EAAM,MAAM,EAAI,SAAS,WAAW,GAAO,EAGjD,OAFK,EAAI,IAEF,MADY,EAAI,KAAK,EAAA,CAChB,QAAU,CAAC,EAFH,CAAC,CAGvB,CAEA,SAAgB,kBAAkB,EAA4B,CAC5D,GAAI,EAAM,YAAa,OAAO,EAAI,OAAO,EAAM,WAAW,EAE1D,IAAM,EAAY,EAAM,YAAc,kBAAkB,CAAK,EAC7D,OAAO,EAAI,OAAO,WAAW,EAAU,SAAS,CAClD,CAOA,eAAsB,gBACpB,EACkC,CAMlC,OAJkB,MADG,YAAY,CAAE,KAAM,CAAK,CAAC,EAAA,CACtB,KAAM,GAAM,EAAE,OAAS,CAC5C,IAGG,MADc,YAAY,CAAE,cAAe,CAAK,CAAC,EAAA,CAC1C,KAAM,GAAM,EAAE,OAAS,CAAI,CAC3C,CAEA,eAAsB,qBACpB,EACwB,CACxB,GAAI,CACF,IAAM,EAAQ,MAAM,gBAAgB,CAAI,EAGxC,OAFK,GAAO,WAEL,kBAAkB,CAAK,EAFC,IAGjC,MAAQ,CACN,OAAO,IACT,CACF,CAEA,eAAsB,iBACpB,EACA,EACe,CACf,GAAI,CACF,IAAM,EAAQ,MAAM,gBAAgB,CAAI,EACxC,GAAI